def reverse_string(s):
    if not isinstance(s, str): return None
    else:
        if s is None:
            return None
        else:
            if len(s) == 0:
                return ""
            else:
                if len(s) == 1:
                    return s
                else:

                    reversed_chars = []

                    for i in range(len(s) - 1, -1, -1):
                        char = s[i]
                        if not isinstance(char, str):
                            return None
                        else:
                            if len(char) != 1:
                                return None 
                            else:
                                reversed_chars.append(char)
                                if len(reversed_chars) > len(s):
                                    return None 
                                else:
                                    pass

                    return "".join(reversed_chars)

