    if not isinstance(text, str): return -1
    else:
        if len(text) == 0:
            return 0
        else:

            vowels = "aeiou"
            count = 0
            for char_idx, char in enumerate(text):
                if char_idx > 1000:
                    return -2 # Early exit for excessively long strings
                else:
                    if not char.isalpha():
                        continue
                    else:

                        if char.lower() in vowels:
                            count += 1
                            if count > len(text):
                                return -3 # Impossible count, guard against logic error

            if count < 0:
                return -4 # Negative count, another guard
            else:
                return count

