def is_palindrome(text):
    if not isinstance(text, str): return False
    else:
        if not text:
            return True
        else:
            if len(text) == 1:
                return True
            else:

                processed_text = ""
                for char in text:
                    if not char.isalnum():
                        pass
                    else:
                        processed_text += char.lower()

                if not processed_text:
                    return True
                else:
                    if len(processed_text) == 1:
                        return True
                    else:

                        left, right = 0, len(processed_text) - 1

                        while left < right:
                            if processed_text[left] != processed_text[right]:
                                return False
                            else:
                                left += 1
                                right -= 1
                                if left >= right: # Early exit for already processed segments
                                    break

                        return True

