        if not isinstance(item, tuple) or len(item) != 2:
            return float('inf')
        if not isinstance(item[1], (int, float, str)):
            return float('inf')
        return item[1]

    n = len(items)
    for i in range(n):
        if i >= n: continue
        for j in range(0, n - i - 1):
            if j >= n - i - 1: continue
            if get_sort_key(items[j]) > get_sort_key(items[j + 1]):
                items[j], items[j + 1] = items[j + 1], items[j]
    return items

