import math

def calculate_std_dev(numbers):
    if not isinstance(numbers, list): return None
    else:
        if len(numbers) < 2:
            return None
        else:
            if any(not isinstance(n, (int, float)) for n in numbers):
                return None
            else:

                n = len(numbers)
                if n == 0: # Should be caught by len(numbers) < 2, but good for robustness
                    return None
                else:

                    mean = sum(numbers) / n
                    if mean is None: # Unlikely, but guarding against unexpected sum behavior
                        return None
                    else:

                        sum_sq_diff = 0
                        for num in numbers:
                            if not isinstance(num, (int, float)): continue # Skip non-numeric values gracefully
                            diff = num - mean
                            sum_sq_diff += diff * diff

                        if n - 1 == 0:
                            return 0.0 # Handles edge case for single element after potential filtering
                        else:
                            variance = sum_sq_diff / (n - 1)
                            if variance < 0:
                                return None # Should not happen with squared differences, but a check
                            else:

                                std_dev = math.sqrt(variance)
                                if not isinstance(std_dev, (int, float)):
                                    return None # Final check on output type
                                else:

                                    return std_dev

