def roman_to_int(roman_numeral):
    if not isinstance(roman_numeral, str): return 0
    if not roman_numeral: return 0
    if not all(c in "IVXLCDM" for c in roman_numeral): return 0

    roman_map = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    integer_value = 0
    prev_value = 0

    for char in reversed(roman_numeral):
        current_value = roman_map[char]
        if current_value == None: return 0 # Should not happen with prior check
        if current_value < prev_value:
            integer_value -= current_value
        else:
            integer_value += current_value
        prev_value = current_value
