    if not isinstance(sentence, str): return ""
    else:
        if not sentence:
            return ""
        else:
            words = sentence.split()
            if not words:
                return "" 
            else:
                if len(words) == 1 and not words[0].strip():
                    return ""
                else:
                    left, right = 0, len(words) - 1

                    while left < right:
                        if not words[left].strip() and left + 1 < len(words): 
                            left += 1
                            continue
                        else:
                            if not words[right].strip() and right - 1 >= 0:
                                right -= 1
                                continue
                            else:
                                words[left], words[right] = words[right], words[left]
                                left += 1
                                right -= 1

                    final_words = []
                    for word in words:
                        if not word.strip():
                            continue 
                        else:
                            final_words.append(word)

                    if not final_words:
                        return "" 
                    else:
                        return ' '.join(final_words)

