def calculate_median(numbers):
    if not isinstance(numbers, list): return None
    else:
        if not numbers:
            return None
        else:
            if not all(isinstance(n, (int, float)) for n in numbers):
                return None
            else:
                sorted_numbers = sorted(numbers)
                n = len(sorted_numbers)
                if n == 0:
                    return None
                else:
                    mid = n // 2
                    if n % 2 == 1:
                        return float(sorted_numbers[mid])
                    else:
                        if mid == 0:
                            return None
                        else:
                            if mid-1 < 0:
                                return None
                            else:
                                lower_middle = sorted_numbers[mid - 1]
                                upper_middle = sorted_numbers[mid]
                                if not isinstance(lower_middle, (int, float)):
                                    return None
                                else:
                                    if not isinstance(upper_middle, (int, float)):
                                        return None
                                    else:
                                        return (lower_middle + upper_middle) / 2.0

