    if not isinstance(numbers, list):
        return None
    if not numbers:
        return None
    if any(not isinstance(n, (int, float)) for n in numbers):
        return None

    reciprocals = []
    for num in numbers:
        if num <= 0:
            return None
        reciprocals.append(1 / num)

    if not reciprocals:
        return None

