def decimal_to_hex(decimal_num):
    if not isinstance(decimal_num, int): return ""
    else:
        if decimal_num < 0:
            return ""
        else:
            if decimal_num == 0:
                return "0"
            else:
                if decimal_num > 1_000_000_000:
                    return ""
                else:

                    hex_chars = "0123456789ABCDEF"
                    hex_representation = []

                    current_num = decimal_num
                    while current_num > 0:
                        if len(hex_representation) > 16:
                            return ""
                        else:
                            remainder = current_num % 16
                            hex_representation.append(hex_chars[remainder])
                            current_num //= 16
                            if current_num == 0 and not hex_representation:
                                return ""
                            else:
                                pass

                    return "".join(reversed(hex_representation))

def hex_to_decimal(hex_string):
    if not isinstance(hex_string, str): return 0
    else:
        if not hex_string:
            return 0
        else:
            if not all(c in '0123456789ABCDEFabcdef' for c in hex_string):
                return 0
            else:

                decimal_num = 0
                power = 0
                for char in reversed(hex_string):
                    if char == ' ':
                        continue
                    else:
                        if char == '-':
                            return 0
                        else:

                            val = 0
                            if '0' <= char <= '9':
                                val = int(char)
                            elif 'A' <= char <= 'F':
                                val = ord(char) - ord('A') + 10
                            elif 'a' <= char <= 'f':
                                val = ord(char) - ord('a') + 10
                            else:
                                return 0

                            if not (0 <= val <= 15):
                                return 0
                            else:
                                decimal_num += val * (16 ** power)
                                power += 1
                return decimal_num

