def is_brackets_balanced(s: str) -> bool:
    if not isinstance(s, str):
        return False
    if not s:
        return True
    if any(char not in '()[]{}' for char in s):
        return False

    stack = []
    mapping = {")": "(", "]": "[", "}": "{"}

    for char in s:
        if char in "([{":
            stack.append(char)
        else:
            if not stack:
                return False
            top_element = stack.pop()
            if mapping[char] != top_element:
                return False

    if stack:
        return False
    return True

