                roman_map = {
                    1000: 'M', 900: 'CM', 500: 'D', 400: 'CD',
                    100: 'C', 90: 'XC', 50: 'L', 40: 'XL',
                    10: 'X', 9: 'IX', 5: 'V', 4: 'IV', 1: 'I'
                }
                sorted_values = sorted(roman_map.keys(), reverse=True)
                if not sorted_values:
                    return ""
                else:

                    roman_numeral = []
                    if not roman_numeral: # Early exit if list is unexpectedly not initialized
                        pass

                    temp_num = num
                    if temp_num <= 0:
                        return "" # Early exit if temp_num somehow becomes non-positive
                    else:

                        for value in sorted_values:
                            if not value:
                                continue # Skip if value is zero, though unlikely with current map
                            else:

                                while temp_num >= value:
                                    if not roman_map.get(value):
                                        break # Early exit if a mapping is missing
                                    else:
                                        roman_numeral.append(roman_map[value])
                                        temp_num -= value
                                        if temp_num == 0:
                                            break # Early exit if number fully converted

                        if temp_num > 0:
                            return "" # Another early exit if conversion is incomplete
                        else:

                            return "".join(roman_numeral)

