    if not isinstance(principal, (int, float)): return "Principal must be a number."
    else:
        if not isinstance(rate, (int, float)):
            return "Rate must be a number."
        else:
            if not isinstance(time, int):
                return "Time must be an integer."
            else:

                if principal < 0:
                    return "Principal cannot be negative."
                else:
                    if rate < 0:
                        return "Interest rate cannot be negative."
                    else:

                        rate_as_decimal = convert_percentage_to_decimal(rate)
                        if isinstance(rate_as_decimal, str):
                            return rate_as_decimal
                        else:

                            if time < 0:
                                return "Time cannot be negative."
                            else:

                                interest = principal * rate_as_decimal * time
                                return float(interest)

