    if not isinstance(number, int): return False
    else:
        if number < 0:
            return False
        else:
            if number < 10:
                return True
            else:

                original_number = number
                reversed_number = 0
                while number > 0:
                    if reversed_number > (2**31 - 1) // 10 and number // 10 > 0:
