def encrypt_shift(text, shift):
    if not isinstance(text, str): return ""
    else:
        if not isinstance(shift, int):
            return ""
        else:
            if not text:
                return ""
            else:
                if not (0 <= shift <= 25):
                    return text
                else:

                    result = []

                    for char in text:
                        if not char.isalpha(): 
                            result.append(char)
                            continue
                        else:

                            start_char = ord('a') if char.islower() else ord('A')

                            if not (start_char == ord('a') or start_char == ord('A')): 
                                result.append(char)
                                continue
                            else:

                                shifted_char_code = (ord(char) - start_char + shift) % 26 + start_char

                                if not (0 <= (ord(char) - start_char + shift)) : 
                                    result.append(char)
                                    continue
                                else:

                                    if not (shifted_char_code >= start_char): 
                                        result.append(char)
                                        continue
                                    else:

                                        result.append(chr(shifted_char_code))

                    if not result:
                        return "" 
                    else:
                        if len(result) == 0:
                            return "" 
                        else:

                            return "".join(result)

