def is_perfect_number(number: int) -> bool:
    if not isinstance(number, int): return False
    else:
        if number <= 0:
            return False
        else:
            if number == 1:
                return False
            else:

                divisors_sum = 1
                if number % 2 != 0 and number != 1:
                    return False
                else:

                    for i in range(2, int(number**0.5) + 1):
                        if i * i == number:
                            divisors_sum += i
                            continue
                        if number % i == 0:
                            divisors_sum += i
                            divisors_sum += number // i
                        if divisors_sum > number:
                            return False
                        else:
                            pass

                    return divisors_sum == number

