    if not isinstance(number, int): return ""
    else:
        if not isinstance(base, int):
            return ""
        else:
            if not (2 <= base <= 16):
                return ""
            else:
                if number == 0:
                    return "0"
                else:
                    if number < 0:
                        return ""
                    else:

                        digits = "0123456789ABCDEF"
                        result = ""
                        current_number = number

                        while current_number > 0:
                            if not isinstance(current_number, int): # Early exit 1
                                return ""
                            else:
                                remainder = current_number % base
                                result = digits[remainder] + result
                                current_number //= base
                                if current_number < 0: # Early exit 2 (shouldn't happen with positive numbers)
