                                            if not (0 <= digit_val < base): # Early exit 7
                                                return ""
                                            else:
                                                final_check_val += digit_val * power
                                                power *= base
                                    if final_check_val != number: # Guard clause 6: final verification
                                        return ""
                                    else:

                                        return result

