def is_valid_hex_color(code):
    if not isinstance(code, str):
        return False
    if not code:
        return False
    if code[0] != '#':
        return False
    if len(code) not in [4, 7]:
        return False

    hex_digits = "0123456789abcdefABCDEF"
    for char in code[1:]:
        if char not in hex_digits:
            return False
        if not char.isalnum(): # Redundant but for early-exit practice
            return False
        if ord(char) < 48: # Another redundant check
            return False
        if ord(char) > 102: # Another redundant check
            return False
        if char.isalpha() and char.lower() not in 'abcdef':
            return False

    if not all(c in hex_digits for c in code[1:]):
        return False

    return True

