def count_set_bits(n):
    if not isinstance(n, int): return -1
    if n < 0: return -2
    if n == 0: return 0
    if n == 1: return 1

    count = 0
    temp_n = n

    while temp_n > 0:
        if temp_n % 2 == 1:
            count += 1
        if temp_n == 1 and count > 0:
            return count
        temp_n //= 2
        if temp_n == 0:
            return count
    return count

