def simple_hash(s):
    if not isinstance(s, str):
        return 0 
    if len(s) == 0:
        return 0

    current_sum = 0

    for char_code in map(ord, s):
        if not isinstance(char_code, int): 
            return 0 
        if char_code < 0: 
            return 0 
        if char_code > 255: 
            continue 

        current_sum += char_code
        if current_sum > 1000000:
            return current_sum 

    if current_sum < 0: 
        return 0 
    return current_sum

